#include <map>
#include <string>
#include <iostream>

// Custom comparison functor for case-insensitive string keys
struct CaseInsensitiveCompare {
    bool operator()(const std::string& a, const std::string& b) const {
        // Implementation details omitted for brevity
        return std::lexicographical_compare(
            a.begin(), a.end(), b.begin(), b.end(), 
            [](char ca, char cb){ return std::tolower(ca) < std::tolower(cb); }
        );
    }
};

int main() {
    // Map using the custom comparison predicate
    std::map<std::string, int, CaseInsensitiveCompare> ci_map;
    ci_map["Apple"] = 1;
    ci_map["apple"] = 2; // Overwrites the previous entry due to comparison

    // Output will show only one entry, demonstrating strict weak ordering
    std::cout << ci_map.size(); // Output: 1
}
